// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetCatalog List every operation the signed-in person may call.
	// (GET /api/catalog)
	GetCatalog(ctx context.Context, request GetCatalogRequestObject) (GetCatalogResponseObject, error)
	// GetHealth Report whether the platform is up.
	// (GET /api/health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// PostInvoke Execute a confirmed call against a service.
	// (POST /api/invoke)
	PostInvoke(ctx context.Context, request PostInvokeRequestObject) (PostInvokeResponseObject, error)
	// ListOperations List every operation across every configured service.
	// (GET /api/operations)
	ListOperations(ctx context.Context, request ListOperationsRequestObject) (ListOperationsResponseObject, error)
	// PostPlan Turn a question into a decision and, when safe, its result.
	// (POST /api/plan)
	PostPlan(ctx context.Context, request PostPlanRequestObject) (PostPlanResponseObject, error)
	// DeleteSession Sign out.
	// (DELETE /api/session)
	DeleteSession(ctx context.Context, request DeleteSessionRequestObject) (DeleteSessionResponseObject, error)
	// GetSession Who is signed in.
	// (GET /api/session)
	GetSession(ctx context.Context, request GetSessionRequestObject) (GetSessionResponseObject, error)
	// PostSession Sign in.
	// (POST /api/session)
	PostSession(ctx context.Context, request PostSessionRequestObject) (PostSessionResponseObject, error)
	// ListUsers List every account.
	// (GET /api/users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// GetUserPermissions Read one account's permissions.
	// (GET /api/users/{id}/permissions)
	GetUserPermissions(ctx context.Context, request GetUserPermissionsRequestObject) (GetUserPermissionsResponseObject, error)
	// SetUserPermissions Replace one account's permissions, wholesale.
	// (PUT /api/users/{id}/permissions)
	SetUserPermissions(ctx context.Context, request SetUserPermissionsRequestObject) (SetUserPermissionsResponseObject, error)
	// ListWorkspaces List the stub owner's workspaces.
	// (GET /api/workspaces)
	ListWorkspaces(ctx context.Context, request ListWorkspacesRequestObject) (ListWorkspacesResponseObject, error)
	// CreateWorkspace Create an empty workspace.
	// (POST /api/workspaces)
	CreateWorkspace(ctx context.Context, request CreateWorkspaceRequestObject) (CreateWorkspaceResponseObject, error)
	// DeleteWorkspace Delete a workspace and every panel it holds.
	// (DELETE /api/workspaces/{id})
	DeleteWorkspace(ctx context.Context, request DeleteWorkspaceRequestObject) (DeleteWorkspaceResponseObject, error)
	// GetWorkspace Read one workspace and its panels, in position order.
	// (GET /api/workspaces/{id})
	GetWorkspace(ctx context.Context, request GetWorkspaceRequestObject) (GetWorkspaceResponseObject, error)
	// AddPanel Save a call as a panel on a workspace.
	// (POST /api/workspaces/{id}/panels)
	AddPanel(ctx context.Context, request AddPanelRequestObject) (AddPanelResponseObject, error)
	// DeletePanel Remove one panel from a workspace.
	// (DELETE /api/workspaces/{id}/panels/{panelId})
	DeletePanel(ctx context.Context, request DeletePanelRequestObject) (DeletePanelResponseObject, error)
	// UpdatePanel Change one or more fields of an existing panel.
	// (PATCH /api/workspaces/{id}/panels/{panelId})
	UpdatePanel(ctx context.Context, request UpdatePanelRequestObject) (UpdatePanelResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

